// Profile.js (Frontend - React)
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

import { useParams } from 'react-router-dom'; // For dynamic routing
//import './Profile.css'; // Import your CSS file


function Profile() {
    const { email } = useParams(); // Get email from URL parameter
    const [userData, setUserData] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);



    useEffect(() => {

        const fetchUserData = async () => {
          try {
                const storedEmail = localStorage.getItem('email');
                if (!storedEmail) {
                    // Handle the case where email is not found in local storage (e.g., redirect to login)
                    setError("Email not found in local storage. Please login.");
                    setLoading(false);
                    return;
                }
                const response = await axios.get(`http://localhost:8000/savings/${storedEmail}`);
                setUserData(response.data);
                setLoading(false);
            } catch (err) {
                setError("Error fetching user data. Please try again later.");
                setLoading(false);
                console.error(err);
            }
        };

        fetchUserData();
    }, []);



    if (loading) {
        return <div>Loading user data...</div>;
    }

    if (error) {
        return <div>Error: {error}</div>;
    }

    if (!userData) {
        return <div>User not found.</div>;
    }

    return (
        <>
        <div className="profile-container">  {/* Use your CSS class here */}
            <h2>Profile</h2>
            <p><strong>Name:</strong> {userData.name}</p>
            <p><strong>Email:</strong> {userData.email}</p>
            <p><strong>Father's Name:</strong> {userData.fatherName}</p>
            <p><strong>Mother's Name:</strong> {userData.motherName}</p>
            <p><strong>Age:</strong> {userData.age}</p>
            <p><strong>Date of Birth:</strong> {userData.dob}</p>
            <p><strong>Balance:</strong> {userData.balance}</p>
            {/* Add more fields as needed */}
        </div>
        <div className="App">
      <section className="services-section">
        <h2>Our Services</h2>
        <div className="services">
          <Link to="/savings" className="service-card">
            <span className="icon">🐖</span>
            <h3>Savings Account</h3>
            <p>Grow your wealth securely with our high-interest savings accounts.</p>
          </Link>
          <Link to="/credit-cards" className="service-card">
            <span className="icon">💳</span>
            <h3>Credit Cards</h3>
            <p>Flexible credit card options with rewards and cashback offers.</p>
          </Link>
          <Link to="/investment-plans" className="service-card">
            <span className="icon">📈</span>
            <h3>Investment Plans</h3>
            <p>Strategic investment solutions to help you achieve your financial goals.</p>
          </Link>
          <Link to="/loans" className="service-card">
            <span className="icon">🏦</span>
            <h3>Loans</h3>
            <p>Personalized loan options to meet your financial needs.</p>
          </Link>
          <Link to="/mobile-banking" className="service-card">
            <span className="icon">📱</span>
            <h3>Mobile Banking</h3>
            <p>Access your accounts anytime, anywhere with our mobile banking app.</p>
          </Link>
          <Link to="/insurance" className="service-card">
            <span className="icon">🛡️</span>
            <h3>Insurance</h3>
            <p>Comprehensive insurance plans to protect your future.</p>
          </Link>
          <Link to="/balance-checking" className="service-card">
            <span className="icon">🔍</span>
            <h3>Balance Checking</h3>
            <p>Stay updated with your account balance and transaction history.</p>
          </Link>
        </div>
      </section>

      <footer>
        <div className="footer-links">
          <a href="#privacy">Privacy Policy</a>
          <a href="#terms">Terms of Service</a>
          <a href="#help">Help Center</a>
        </div>
        <p>©️ 2024 Digibank all rights reserved</p>
      </footer>
    </div>

        </>
    );
}


export default Profile;
